#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-09-06

# Test: scripts/ci/check-skill-structure.sh fails when its input is absent.
#
# Why (gate-fault-arm audit, docs/audits/gate-fault-arm-audit-2026-09-06.md):
#
# plugin-validation.yml "Validate skill structure" was an inline step that
# checked `[[ -d skills ]]` at the checkout root and exited 0 when it was
# missing. The repo has had no root skills/ since the plugins/ restructure, so
# the gate exited 0 on every run and never looked at a skill. Measured in the
# audit: control 0, fault (no dir) 0. The logic now lives in a script pointed
# at plugins/ork/skills, and both absent-input shapes fail.
#
# Arms:
#   control: one skill with SKILL.md            -> exit 0
#   control2: the real built tree               -> exit 0 (skipped if not built)
#   fault:   skills dir missing                 -> exit 1
#   fault2:  skills dir present, zero skills    -> exit 1
#   fault3:  one skill without SKILL.md         -> exit 1

set -euo pipefail
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
CHECK="$REPO_ROOT/scripts/ci/check-skill-structure.sh"
WF="$REPO_ROOT/.github/workflows/plugin-validation.yml"

echo "=== check-skill-structure fault arms ==="
echo ""

WORK="$(mktemp -d "${TMPDIR:-/tmp}/ork-skill-structure.XXXXXX")"
trap 'rm -rf "$WORK"' EXIT

PASS=0; FAIL=0
ok()  { echo "  PASS: $1"; PASS=$((PASS + 1)); }
bad() { echo "  FAIL: $1"; FAIL=$((FAIL + 1)); }
rc_of() { local rc=0; bash "$CHECK" "$1" >/dev/null 2>&1 || rc=$?; echo "$rc"; }  # silent: rc is the assertion

mkdir -p "$WORK/control/a"; echo x > "$WORK/control/a/SKILL.md"
[[ "$(rc_of "$WORK/control")" == "0" ]] && ok "control: one skill with SKILL.md exits 0" || bad "control: one skill with SKILL.md should exit 0"

if [[ -d "$REPO_ROOT/plugins/ork/skills" ]]; then
  [[ "$(rc_of "$REPO_ROOT/plugins/ork/skills")" == "0" ]] && ok "control2: built plugins/ork/skills exits 0" || bad "control2: built plugins/ork/skills should exit 0"
else
  echo "  SKIP: control2, plugins/ork/skills not built"
fi

[[ "$(rc_of "$WORK/missing")" != "0" ]] && ok "fault: missing skills dir exits non-zero" || bad "fault: missing skills dir exited 0"

mkdir -p "$WORK/empty"
[[ "$(rc_of "$WORK/empty")" != "0" ]] && ok "fault2: zero skills exits non-zero" || bad "fault2: zero skills exited 0"

mkdir -p "$WORK/nomd/a"
[[ "$(rc_of "$WORK/nomd")" != "0" ]] && ok "fault3: skill without SKILL.md exits non-zero" || bad "fault3: skill without SKILL.md exited 0"

# The workflow must call the script, not carry its own inline copy of the old
# `[[ ! -d "skills" ]] ... exit 0` early-out.
if grep -q 'scripts/ci/check-skill-structure.sh' "$WF" && ! grep -q 'No skills directory found' "$WF"; then
  ok "plugin-validation.yml calls check-skill-structure.sh and has no inert early-out"
else
  bad "plugin-validation.yml does not call check-skill-structure.sh, or still carries the inert early-out"
fi

echo ""
echo "Results: $PASS passed, $FAIL failed"
[[ $FAIL -eq 0 ]]
